def pi(p):
    pK={'K':10.5,'R':12.5,'H':6.0,'D':3.9,'E':4.3,'C':8.3,'Y':10.1}
    def charge(ph):
        c=1/(1+10**(ph-9.6)) - 1/(1+10**(2.4-ph))
        for a,cnt in Counter(p).items():
            if a in pK:
                if a in 'KRH': c+=cnt/(1+10**(ph-pK[a]))
                elif a in 'DECY': c-=cnt/(1+10**(pK[a]-ph))
        return c
    lo,hi=0,14
    for _ in range(80):
        mid=(lo+hi)/2
        if charge(mid)>0: lo=mid
        else: hi=mid
    return (lo+hi)/2
