# promoter scan
def one_mm(pattern,text,off):
    out=[]
    for i in range(len(text)-len(pattern)+1):
        mm=sum(1 for a,b in zip(pattern,text[i:i+len(pattern)]) if a!=b)
        if mm<=1: out.append((i+off,mm))
    return out
def prom(name,s,off):
    hits=[]
    for a,m1 in one_mm('TTGACA',s,off):
        for b,m2 in one_mm('TATAAT',s,off)+one_mm('TATTAT',s,off):
            if 15<=b-(a+6)<=19: hits.append((a,b,m1+m2))
    hits=sorted(set(hits),key=lambda x:x[2])
    print(name,'-35/-10 pairs (<=1mm each):',hits[:10])
